bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
set +e
docker exec -i "$cid" node --input-type=module <<'NODE'
import {openCreatorEditor,creatorEditorPanel} from '/opt/videobot/src/telegram/creatorUi.mjs';
const e=openCreatorEditor({sellerId:'123456',existing:{id:'test',sellerId:'123456',revision:2,title:'test',paidVideo:{fileId:'abc123'}}});
const p=creatorEditorPanel(e,7);
const cb=p.reply_markup.inline_keyboard.flat().map(b=>String(b.callback_data||'').split('|')[0]);
const stems=['entry:register','edit:save','edit:update','edit:preview','edit:register','video:save','edit:cancel','edit:return'];
const mask=stems.reduce((n,s,i)=>n+(cb.includes(s)?1<<i:0),0);
process.exit(100+mask);
NODE
exit "$?"
